-- aolangai: the quota and open sessions of every Claude account on one Mac, and work handed to the account
-- with the most quota left (OpenYard team project).
-- Its site, aolangai.openyard.cloud, is not deployed yet, so `url` is the repository for now.
INSERT INTO projects (slug, name, type, kinds, status, tagline, description, url, repo, license, logo, logo_style, image, og, color, maintainers, tags, team, featured, swarm, added, created_at, updated_at, install) VALUES
('aolangai', 'aolangai', 'open-source', '["dev"]', 'beta',
 '{"en":"See all your Claude accounts'' quota, and delegate to the one with the most left","vi":"Xem quota của mọi account Claude ở một chỗ, và giao việc cho account còn nhiều nhất"}',
 '{"en":"For people with more than one Claude subscription account on one Mac. A macOS app shows the quota of every account and the Claude Code sessions open on the machine, in one window and in the menu bar, and has an Open Terminal button that starts Claude Code on another account. The aolangai command lets a Claude Code session hand a piece of work to the account with the most quota left, so subagent work stops draining the account you are using. It never reads or stores a login token, and the only claude it runs is the one you installed. Using several accounts is a gray area under Anthropic''s terms: read the note in the README first. Not affiliated with Anthropic.","vi":"Dành cho người có nhiều account Claude trả phí trên cùng một máy Mac. App macOS hiện quota của từng account và các phiên Claude Code đang mở trên máy, trong một cửa sổ và trên thanh menu, kèm nút Open Terminal để mở Claude Code bằng account khác. Lệnh aolangai cho một phiên Claude Code giao một phần việc cho account còn nhiều quota nhất, để việc của subagent không ăn vào account bạn đang dùng. App không đọc hay lưu token đăng nhập, và chỉ chạy lệnh claude do chính bạn cài. Dùng nhiều account là vùng xám theo điều khoản của Anthropic: hãy đọc phần lưu ý trong README trước. Dự án độc lập, không thuộc Anthropic."}',
 'https://github.com/openyard-cloud/aolangai', 'https://github.com/openyard-cloud/aolangai', 'MIT',
 '/logos/aolangai.svg', 'tile', '/images/aolangai.webp', NULL, '#b8501c',
 '["egan-vo"]', '["claude-code","macos","developer-tools"]', 1, 1, NULL,
 '2026-11-19', 1795084144799, 1795084144799,
 '[{"label":{"en":"macOS (Apple silicon)","vi":"macOS (Apple silicon)"},"cmd":"git clone https://github.com/openyard-cloud/aolangai.git && cd aolangai && npm install && npm run dist","note":{"en":"Builds apps/desktop/release/mac-arm64/aolangai.app: drag it into Applications and open it. Needs Claude Code and, only to build, Node 22.13 or newer. There is no download yet.","vi":"Build ra apps/desktop/release/mac-arm64/aolangai.app: kéo vào Applications rồi mở. Cần có Claude Code, và Node 22.13 trở lên (chỉ để build). Chưa có bản tải sẵn."}}]');
